`src/envs/dev/infra/logs.ts`
```typescript
/**
 * dev environment — application logs bucket.
 *
 * Discovered by `chant build src/envs/dev/infra` alongside `main.ts`, so the
 * bucket and its reader identity land in the same output. Same composites as
 * the assets bucket: `SecureBucket` already pins versioning, encryption, and
 * the public-access block, so criterion 1 needs no props here.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-dev";

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

// Scoped to the logs bucket only — no wildcard action, no wildcard resource.
// `s3:GetObject` comes from the baseline reader policy; `s3:PutObject` is
// enumerated here.
export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  component: "logs",
});
```

`src/envs/prod/infra/logs.ts`
```typescript
/**
 * prod environment — application logs bucket.
 *
 * The prod counterpart of `../../dev/infra/logs.ts`, declared independently:
 * this arm has no parameterized entrypoint, so each environment owns its own
 * call site. Trust matches the environment's existing `reader` (OIDC, same
 * provider ARN and issuer host, namespace `app`, service account `myapp`).
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-prod";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  trust: {
    mode: "oidc",
    providerARN:
      "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  component: "logs",
});
```

Notes: no file under `src/composites/` is touched, and no raw resource is hand-written. Each `ReaderIam` uses a distinct base name (`myapp-{env}-logs`) so its `Policy`/`Role` names don't collide with the existing `myapp-{env}` reader, and its policy document resolves only to `arn:aws:s3:::myapp-logs-{env}` (bucket ARN for `s3:ListBucket`, object ARN for the enumerated object actions) — the assets bucket is untouched.
